import json, math
FORMES_IT = {"peggiore": ["peggiore", "peggiori"], "marrone": ["marrone", "marroni"]}
exec(open("/home/claude/pm_italien/freq2.py").read())
P = "/home/claude/pm_italien/data_italien.json"
d = json.load(open(P))
info = json.load(open(f"{S}/adj_fr.json"))
ordre = list(info["adj"].keys()) + "blanc rouge orange jaune vert bleu violet marron rose gris".split()
niches = []
for line in [l for l in A.strip().split("\n") if l.strip()]:
    p = line.split("|"); assert len(p) == 15, (len(p), line[:40])
    key, frl, itl, iw, pr, api, mc, sc, de, fo, efr, mfr, eit, mit, li = p
    lex = key.split("+")
    f = fr(lex, ["ADJ"]); i = it(iw, "ADJ", formes=FORMES_IT.get(iw))
    assert f and i, (key, iw, f, i)
    for a, b in ((efr, mfr), (eit, mit)): assert b in a, (key, a, b)
    niches.append(dict(fr=frl, cible=itl, prononciation=pr, api=f"/{api}/", mot_cle=mc, scene=sc, decryptage=de,
        formes=fo, exemple_fr=efr, exemple_fr_mot=mfr, exemple_cible=eit, exemple_cible_mot=mit, lien=li,
        categorie="adjectifs_qualificatifs", sous_categories=["adjectifs_qualificatifs"] + (["adjectifs_couleurs"] if len(niches) >= 90 else []),
        lex=lex, lemme_it=iw, audio_mot=None, audio_phrase=None,
        zipf={"fr": f, "it": i}, zipf_fr=f["parle"], zipf_cible=i["parle"], zipf_source="mesuré", _key=key))
got = [n["_key"] for n in niches]
assert got == ordre, [(a, b) for a, b in zip(got, ordre) if a != b][:5]
assert len({n["cible"] for n in niches}) == 100 and len({n["fr"] for n in niches}) == 100
for k, n in enumerate(niches):
    n["n"] = k; n.pop("_key")
    n["occ100M"] = {lg: {kk: int(round(10 ** (v - 1), -int(math.floor(v - 1)) + 2)) for kk, v in sc_.items() if v}
                    for lg, sc_ in n["zipf"].items()}
d["pieces"] = [p for p in d["pieces"] if p["id"] != "adjectifs"]
d["pieces"].insert(2, {"id": "adjectifs", "titre_fr": "Les adjectifs qualificatifs", "titre_cible": "Gli aggettivi",
    "decor": "galerie de peinture", "ordre": "00-89 : Zipf FR parlé décroissant ; 90-99 : couleurs MemoHugoDate (x0 blanc … x9 gris)",
    "blocs": [None] * 9 + ["couleurs (code MemoHugoDate)"], "niches": niches})
json.dump(d, open(P, "w"), ensure_ascii=False, indent=1)
print("ok", len(niches))
